def can_have_same_days(day1, day2):
    days = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]
    day1_index = days.index(day1)
    day2_index = days.index(day2)

    for year in range(2023, 2100):
        for month in range(1, 13):
            first_day = calendar.weekday(year, month, 1)
            if first_day == day1_index:
                next_month = month % 12 + 1
                next_year = year + (month == 12)
                next_first_day = calendar.weekday(next_year, next_month, 1)
                if next_first_day == day2_index:
                    return True
    return False

